    10	use crate::agreement::{Agree, agreement};
    11	use crate::graph::GraphReach;
    12	use crate::model::Checkpoint;
    13	
    14	pub const CONTRADICTION_PENALTY: f32 = 0.45;
    15	
    16	#[derive(Debug, Clone, Serialize, Deserialize)]
    17	pub struct Ranked {
    18	    pub raw: f32,
    19	    pub scored: f32,
    20	    pub confidence: f32,
    21	    pub tier: String,
    22	    pub verdict: Agree,
    23	    pub why: String,
    24	    pub backed_by: Option<String>,
    25	    pub commit: Option<String>,
    26	    pub text: String,
    27	    pub context: String,
    28	}
    29	
    30	fn source_kind(p: &Option<Provenance>) -> SourceKind {
    31	    match p.as_ref().map(|x| x.kind.clone()) {
    32	        Some(ProvenanceKind::LedgerVerified)
    33	        | Some(ProvenanceKind::ToolGrounded)
    34	        | Some(ProvenanceKind::FileObservation) => SourceKind::Verified,
    35	        Some(ProvenanceKind::UserExplicit) => SourceKind::UserStated,
    36	        _ => SourceKind::Unknown,
    37	    }
    38	}
    39	
    40	pub fn commit_of(ctx: &str) -> Option<String> {
    41	    ctx.split_whitespace()
    42	        .find_map(|t| t.strip_prefix("commit:").map(|s| s.to_string()))
    43	}
    44	
    45	pub fn tier(kind: SourceKind) -> &'static str {
    46	    match kind {
    47	        SourceKind::Verified => "LEDGER",
    48	        SourceKind::UserStated => "INTENT",
    49	        SourceKind::Inferred => "infer",
    50	        SourceKind::Unknown => "chat",
    51	    }
    52	}
    53	
    54	pub fn rerank(recalls: &[RecallResult], cps: &[Checkpoint], g: &GraphReach) -> Vec<Ranked> {
    55	    let by_sha: HashMap<&str, &Checkpoint> =
    56	        cps.iter().map(|c| (c.commit_sha.as_str(), c)).collect();
    57	
    58	    let mut out: Vec<Ranked> = recalls
    59	        .iter()
    60	        .map(|r| {
    61	            let kind = source_kind(&r.episode.provenance);
    62	            let mut ev = vec![Evidence::new(kind, 1.0)];
    63	            let sha = commit_of(&r.episode.context);
    64	            let cp = sha.as_deref().and_then(|k| by_sha.get(k).copied());
    65	            let backed_by = cp.map(|c| format!("{} {}", c.commit_sha, c.commit_message));
    66	            let (verdict, why) = match cp {
    67	                Some(cp) if kind != SourceKind::Verified => agreement(&r.episode.content, cp, g),
    68	                Some(_) => (Agree::Corroborated, "is the commit record".into()),
    69	                None => (Agree::Neutral, "no commit context".into()),
    70	            };
    71	            match verdict {
    72	                // Earned corroboration: an independent verified source.
    73	                Agree::Corroborated if kind != SourceKind::Verified => {
    74	                    ev.push(Evidence::new(SourceKind::Verified, 1.0))
    75	                }
    76	                // Refuted by the ledger: the claim is evidence against itself.
    77	                Agree::Contradicted => ev.push(Evidence::new(SourceKind::Unknown, 0.15)),
    78	                _ => {}
    79	            }
    80	            let mut confidence = recall_confidence(&ev);
    81	            if verdict == Agree::Contradicted {
    82	                confidence *= CONTRADICTION_PENALTY;
    83	            }
    84	            let scored = r.activation * activation_multiplier(confidence);
    85	            Ranked {
    86	                raw: r.activation,
    87	                scored,
    88	                confidence,
    89	                tier: tier(kind).to_string(),
    90	                verdict,
    91	                why,
    92	                backed_by,
    93	                commit: sha,
    94	                text: r.episode.content.replace('\n', " "),
    95	                context: r.episode.context.clone(),
    96	            }
    97	        })
    98	        .collect();
    99	    out.sort_by(|a, b| {
   100	        b.scored
   101	            .partial_cmp(&a.scored)
   102	            .unwrap_or(std::cmp::Ordering::Equal)
   103	    });
   104	    let mut seen = HashSet::new();
   105	    out.retain(|r| seen.insert(r.text.clone()));
   106	    out
   107	}

