     8	/// Three-way verdict of a claim against the commit it sits on.
     9	#[derive(PartialEq, Eq, Clone, Copy, Debug, serde::Serialize, serde::Deserialize)]
    10	#[serde(rename_all = "lowercase")]
    11	pub enum Agree {
    12	    Corroborated,
    13	    Neutral,
    14	    Contradicted,
    15	}
    16	
    17	const ISOLATION: &[&str] = &[
    18	    "isolated",
    19	    "does not touch",
    20	    "nothing else",
    21	    "contained",
    22	    "no other",
    23	];
    24	const NGRAM_THRESHOLD: f32 = 0.10;
    25	const LEXICAL_MIN_SHARED: usize = 2;
    26	
    27	/// Checks run in this order; the first that fires decides.
    28	pub fn agreement(claim: &str, cp: &Checkpoint, g: &GraphReach) -> (Agree, String) {
    29	    let low = claim.to_lowercase();
    30	
    31	    // 1. Scope: claim asserts isolation, Graph says the blast radius escapes.
    32	    if ISOLATION.iter().any(|w| low.contains(w)) {
    33	        let reach = g.escapes(&cp.files);
    34	        if !reach.is_empty() {
    35	            return (
    36	                Agree::Contradicted,
    37	                format!(
    38	                    "claims isolation; Graph reach escapes to {} ({})",
    39	                    reach.len(),
    40	                    reach.join(", ")
    41	                ),
    42	            );
    43	        }
    44	    }
    45	
    46	    // 2. File: claim names a path the commit never touched. URL segments are
    47	    //    not paths: a pasted link must not read as an untouched file.
    48	    let claim_terms = terms(claim);
    49	    for t in claim_terms
    50	        .iter()
    51	        .filter(|t| (t.contains('/') || t.ends_with(".go")) && !looks_like_url(t))
    52	    {
    53	        if !cp
    54	            .files
    55	            .iter()
    56	            .any(|f| f.to_lowercase().contains(t.as_str()))
    57	        {
    58	            return (
    59	                Agree::Contradicted,
    60	                format!("references {t} which this commit did not touch"),
    61	            );
    62	        }
    63	    }
    64	
    65	    // 3. Polarity flip: same topic, opposite action. Conventional-commit
    66	    //    prefixes carry polarity the verb list misses.
    67	    let pc = polarity(claim);
    68	    let mut pm = polarity(&cp.commit_message);
    69	    if pm == 0 {
    70	        let m = cp.commit_message.to_lowercase();
    71	        if m.starts_with("feat") || m.starts_with("fix") || m.starts_with("perf") {
    72	            pm = 1;
    73	        } else if m.starts_with("revert") {
    74	            pm = -1;
    75	        }
    76	    }
