    88	            Agree::Contradicted,
    89	            format!("names {ident}, which the change does not contain"),
    90	        );
    91	    }
    92	
    93	    // 5. Lexical agreement with what the commit says it did.
    94	    let shared = claim_terms.intersection(&commit_terms).count();
    95	    if shared >= LEXICAL_MIN_SHARED {
    96	        return (
    97	            Agree::Corroborated,
    98	            format!("{shared} terms match commit subject"),
    99	        );
   100	    }
   101	
   102	    // 6. Character 4-gram cosine against the diff and file names.
   103	    let corpus = format!(
   104	        "{} {} {}",
   105	        cp.commit_message,
   106	        cp.files.join(" "),
   107	        cp.diff.join(" ")
   108	    );
