   110	    if sim > NGRAM_THRESHOLD {
   111	        return (
   112	            Agree::Corroborated,
   113	            format!("4-gram cosine {sim:.3} with the change"),
   114	        );
   115	    }
   116	
   117	    (Agree::Neutral, "no overlap with commit subject".into())
   118	}
