    41	}
    42	
    43	// recallCommit is a commit on the branch that carries an Entire-Checkpoint trailer.
    44	type recallCommit struct {
    45		SHA          string
    46		Message      string
    47		CheckpointID id.CheckpointID
    48	}
    49	
    50	const (
    51		recallMaxCommits        = 200
