    54	)
    55	
    56	// collectRecallCheckpoints walks HEAD's first-parent history for trailered
    57	// commits and reads each one's checkpoint into the wire shape.
    58	func collectRecallCheckpoints(ctx context.Context, errW io.Writer, root string) (*recallIngestInput, error) {
    59		lookup, err := newExplainCheckpointLookup(ctx)
    60		if err != nil {
    61			return nil, err
    62		}
