   111	func runRecallActivate(ctx context.Context, w, errW io.Writer, question string, k int, asJSON bool) error {
   112		root, err := paths.WorktreeRoot(ctx)
   113		if err != nil {
   114			return fmt.Errorf("not a git repository: %w", err)
   115		}
   116		brain := filepath.Join(root, recallBrainDir)
   117		if _, statErr := os.Stat(brain); statErr != nil {
   118			return errors.New("no recall memory yet; run 'entire recall ingest' first")
   119		}
   120		out, err := runRecallBinary(ctx, root, errW, nil, "activate", "--brain", brain, "--k", strconv.Itoa(k), question)
   121		if err != nil {
   122			return err
   123		}
   124		if asJSON {
   125			_, err = io.WriteString(w, out)
   126			return err //nolint:wrapcheck // raw passthrough of the binary's JSON
   127		}
   128		var hits []recallHit
   129		if err := json.Unmarshal([]byte(out), &hits); err != nil {
   130			return fmt.Errorf("parse recall output: %w", err)
   131		}
   132		renderRecallHits(w, question, hits)
   133		return nil
   134	}
