   178	func renderRecallHits(w io.Writer, question string, hits []recallHit) {
   179		fmt.Fprintf(w, "recall: %q\n\n", question)
   180		if len(hits) == 0 {
   181			fmt.Fprintln(w, "  no memories matched; try different words or run 'entire recall ingest' again")
   182			return
   183		}
   184		for i, h := range hits {
   185			mark := map[string]string{
   186				"corroborated": "✓ corroborated",
   187				"contradicted": "✗ CONTRADICTED",
   188			}[h.Verdict]
   189			if mark == "" {
   190				mark = "· unverified"
   191			}
   192			fmt.Fprintf(w, "%2d. [%-6s] score %.2f  conf %.2f  %s\n", i+1, h.Tier, h.Scored, h.Confidence, h.Text)
   193			fmt.Fprintf(w, "    %s — %s\n", mark, h.Why)
   194			if h.BackedBy != nil {
   195				fmt.Fprintf(w, "    commit %s\n", *h.BackedBy)
   196			}
   197			fmt.Fprintln(w)
   198		}
   199	}

