    86		}
    87		input, err := collectRecallCheckpoints(ctx, errW, root)
    88		if err != nil {
    89			return err
    90		}
    91		if len(input.Checkpoints) == 0 {
    92			fmt.Fprintln(w, "No commits with an Entire-Checkpoint trailer on this branch; nothing to ingest.")
    93			return nil
    94		}
    95		payload, err := json.Marshal(input)
    96		if err != nil {
    97			return fmt.Errorf("encode ingest input: %w", err)
    98		}
    99		args := []string{"ingest", "--brain", filepath.Join(root, recallBrainDir)}
   100		if noGraph {
   101			args = append(args, "--no-graph")
   102		}
   103		out, err := runRecallBinary(ctx, root, errW, bytes.NewReader(payload), args...)
   104		if err != nil {
   105			return err
