   136	// runRecallBinary executes the Rust binary with stdin and returns its stdout.
   137	// Its stderr is forwarded so graph warnings reach the user.
   138	func runRecallBinary(ctx context.Context, root string, errW io.Writer, stdin io.Reader, args ...string) (string, error) {
   139		bin, err := recallBinary(root, os.Getenv("ENTIRE_RECALL_BIN"), exec.LookPath, func(p string) bool {
   140			_, statErr := os.Stat(p) //nolint:gosec // p is $ENTIRE_RECALL_BIN (the user's own choice) or a fixed name under the worktree root
   141			return statErr == nil
   142		})
   143		if err != nil {
   144			return "", err
   145		}
   146		cmd := exec.CommandContext(ctx, bin, args...)
   147		cmd.Dir = root
   148		cmd.Stdin = stdin
   149		cmd.Stderr = errW
   150		out, err := cmd.Output()
   151		if err != nil {
   152			return "", fmt.Errorf("recall %s failed: %w", args[0], err)
   153		}
   154		return string(out), nil
   155	}
   156	
   157	// recallBinary locates the Rust binary: $ENTIRE_RECALL_BIN, then `recall` on
   158	// $PATH, then the cargo build inside the repository.
   159	func recallBinary(root, envBin string, lookPath func(string) (string, error), exists func(string) bool) (string, error) {
   160		if envBin != "" {
   161			if exists(envBin) {
   162				return envBin, nil
   163			}
   164			return "", fmt.Errorf("ENTIRE_RECALL_BIN=%s does not exist", envBin)
   165		}
   166		if p, err := lookPath("recall"); err == nil {
   167			return p, nil
   168		}
   169		for _, profile := range []string{"release", "debug"} {
   170			p := filepath.Join(root, "recall", "target", profile, "recall")
   171			if exists(p) {
   172				return p, nil
   173			}
   174		}
   175		return "", errors.New("recall binary not found: run `cargo build --release` in recall/ or set ENTIRE_RECALL_BIN")
   176	}
   177	
   178	func renderRecallHits(w io.Writer, question string, hits []recallHit) {
   179		fmt.Fprintf(w, "recall: %q\n\n", question)
   180		if len(hits) == 0 {
   181			fmt.Fprintln(w, "  no memories matched; try different words or run 'entire recall ingest' again")
   182			return
   183		}
   184		for i, h := range hits {
   185			mark := map[string]string{
   186				"corroborated": "✓ corroborated",
   187				"contradicted": "✗ CONTRADICTED",
   188			}[h.Verdict]
   189			if mark == "" {
   190				mark = "· unverified"
   191			}
   192			fmt.Fprintf(w, "%2d. [%-6s] score %.2f  conf %.2f  %s\n", i+1, h.Tier, h.Scored, h.Confidence, h.Text)
   193			fmt.Fprintf(w, "    %s — %s\n", mark, h.Why)
   194			if h.BackedBy != nil {
   195				fmt.Fprintf(w, "    commit %s\n", *h.BackedBy)
   196			}
   197			fmt.Fprintln(w)
   198		}
   199	}

