     8	pub const STOP: &[&str] = &[
     9	    "the", "a", "an", "and", "or", "to", "of", "in", "is", "it", "this", "that", "we", "you",
    10	    "for", "on", "with", "not", "be", "are", "was", "so", "at", "as", "its", "into", "from", "by",
    11	    "must", "now", "their", "own",
    12	];
