    14	/// Content terms: lowercase, > 3 chars, stop words removed. Keeps `/`, `.`
    15	/// and `_` inside a token so paths and identifiers survive as one term.
    16	pub fn terms(s: &str) -> HashSet<String> {
    17	    s.to_lowercase()
    18	        .split(|c: char| !c.is_alphanumeric() && c != '/' && c != '.' && c != '_')
    19	        .filter(|w| w.len() > 3 && !STOP.contains(w))
    20	        .map(|w| w.to_string())
    21	        .collect()
    22	}
    23	
    24	/// Action polarity — a claim that ADDS while the commit REMOVES is refuted
    25	/// regardless of how many words they share.
    26	///
    27	/// Word-boundary tokens only: substring matching made "wrapper" read as the
    28	/// verb "wrap", cancelling polarity to zero and silently disabling this check.
    29	pub fn polarity(text: &str) -> i8 {
    30	    let t = text.to_lowercase();
    31	    let toks: HashSet<&str> = t.split(|c: char| !c.is_alphanumeric()).collect();
    32	    const ADD: &[&str] = &[
    33	        "add",
    34	        "adding",
    35	        "added",
    36	        "introduce",
    37	        "introduced",
    38	        "create",
    39	        "created",
    40	        "enable",
    41	        "implement",
    42	        "implemented",
    43	    ];
    44	    const REM: &[&str] = &[
    45	        "remove", "removing", "removed", "delete", "deleted", "drop", "dropped", "revert",
    46	        "reverted", "disable", "strip", "stopped",
    47	    ];
    48	    let a = ADD.iter().filter(|w| toks.contains(*w)).count() as i8;
    49	    let r = REM.iter().filter(|w| toks.contains(*w)).count() as i8;
    50	    (a - r).signum()
    51	}
    52	
    53	/// Split camelCase / snake_case / dotted / slashed identifiers into lowercase
    54	/// pieces, so `maxAttempts` yields {max, attempts}.
    55	pub fn split_ident(w: &str) -> Vec<String> {
    56	    let mut out = Vec::new();
    57	    for part in w.split(['_', '.', '/']) {
    58	        let mut cur = String::new();
    59	        for ch in part.chars() {
    60	            if ch.is_uppercase() && !cur.is_empty() {
    61	                out.push(cur.to_lowercase());
    62	                cur.clear();
    63	            }
    64	            if ch.is_alphanumeric() {
    65	                cur.push(ch);
    66	            }
    67	        }
    68	        if !cur.is_empty() {
    69	            out.push(cur.to_lowercase());
    70	        }
    71	    }
    72	    out.into_iter().filter(|w| w.len() > 2).collect()
    73	}
    74	
    75	/// Vocabulary the change actually introduces: identifier pieces from every
    76	/// diff line plus the touched file paths.
    77	pub fn diff_vocab(cp: &Checkpoint) -> HashSet<String> {
    78	    let mut v = HashSet::new();
    79	    for line in &cp.diff {
    80	        for tok in line.split(|c: char| !c.is_alphanumeric() && c != '_') {
    81	            for piece in split_ident(tok) {
    82	                if piece.len() > 3 && !STOP.contains(&piece.as_str()) {
    83	                    v.insert(piece);
    84	                }
    85	            }
    86	        }
    87	    }
    88	    for f in &cp.files {
    89	        for piece in split_ident(f) {
    90	            if piece.len() > 3 {
    91	                v.insert(piece);
    92	            }
    93	        }
    94	    }
    95	    v
    96	}
    97	
    98	/// Words that LOOK like code: camelCase, snake_case, dotted, `()`-suffixed.
    99	pub fn code_shaped(w: &str) -> bool {
   100	    let has_upper_inside = w.chars().skip(1).any(|c| c.is_uppercase());
   101	    w.contains('_')
   102	        || w.contains("()")
   103	        || (w.contains('.') && !w.ends_with('.'))
   104	        || has_upper_inside
   105	}
   106	
   107	/// Character 4-gram bag — model-free vector similarity, no embedder.
   108	pub fn ngrams(s: &str) -> HashMap<String, f32> {
   109	    let t: String = s
   110	        .to_lowercase()
   111	        .chars()
   112	        .filter(|c| c.is_alphanumeric() || *c == ' ')
   113	        .collect();
   114	    let ch: Vec<char> = t.chars().collect();
   115	    let mut m: HashMap<String, f32> = HashMap::new();
   116	    for w in ch.windows(4) {
   117	        *m.entry(w.iter().collect()).or_insert(0.0) += 1.0;
   118	    }
   119	    m
   120	}
   121	
   122	pub fn cosine(a: &HashMap<String, f32>, b: &HashMap<String, f32>) -> f32 {
   123	    let dot: f32 = a.iter().filter_map(|(k, v)| b.get(k).map(|w| v * w)).sum();
   124	    let na: f32 = a.values().map(|v| v * v).sum::<f32>().sqrt();
   125	    let nb: f32 = b.values().map(|v| v * v).sum::<f32>().sqrt();
   126	    if na * nb == 0.0 { 0.0 } else { dot / (na * nb) }
   127	}
