    18	fn usage() -> ExitCode {
    19	    eprintln!(
    20	        "usage:\n  recall ingest --brain <dir> [--no-graph]   < ingest.json\n  recall activate --brain <dir> [--k N] <question>"
    21	    );
    22	    ExitCode::from(2)
