    25	fn flag(args: &[String], name: &str) -> Option<String> {
    26	    args.iter()
    27	        .position(|a| a == name)
    28	        .and_then(|i| args.get(i + 1).cloned())
    29	}
    30	
    31	fn main() -> ExitCode {
    32	    let args: Vec<String> = std::env::args().skip(1).collect();
    33	    let Some(mode) = args.first() else {
    34	        return usage();
    35	    };
    36	    let Some(brain_dir) = flag(&args, "--brain").map(PathBuf::from) else {
    37	        return usage();
    38	    };
    39	    match mode.as_str() {
    40	        "ingest" => run_ingest(&brain_dir, args.iter().any(|a| a == "--no-graph")),
    41	        "activate" => {
