    43	            let question = args
    44	                .iter()
    45	                .skip(1)
    46	                .enumerate()
    47	                .filter(|(i, a)| {
    48	                    let prev = args.get(*i); // args[i] is the element before args[i+1]
    49	                    !a.starts_with("--") && prev.is_none_or(|p| p != "--brain" && p != "--k")
    50	                })
    51	                .map(|(_, a)| a.as_str())
    52	                .collect::<Vec<_>>()
    53	                .join(" ");
    54	            if question.trim().is_empty() {
