    63	fn run_ingest(brain_dir: &PathBuf, no_graph: bool) -> ExitCode {
    64	    let mut raw = String::new();
    65	    if let Err(e) = std::io::stdin().read_to_string(&mut raw) {
    66	        eprintln!("recall: read stdin: {e}");
    67	        return ExitCode::FAILURE;
    68	    }
    69	    let input: IngestInput = match serde_json::from_str(&raw) {
    70	        Ok(v) => v,
    71	        Err(e) => {
    72	            eprintln!("recall: parse ingest input: {e}");
    73	            return ExitCode::FAILURE;
    74	        }
    75	    };
