    77	        GraphReach::default()
    78	    } else {
    79	        GraphReach::from_entire_graph(&input.repo_root, &input.checkpoints)
    80	    };
    81	    // The brain is derived state: rebuild from scratch so removed checkpoints
    82	    // (rebase, amend) do not linger as stale engrams.
    83	    let _ = std::fs::remove_dir_all(brain_dir);
    84	    if let Err(e) = std::fs::create_dir_all(brain_dir) {
