   119	fn run_activate(brain_dir: &PathBuf, question: &str, k: usize) -> ExitCode {
   120	    let input: IngestInput = match std::fs::read_to_string(brain_dir.join(CHECKPOINTS_FILE))
   121	        .map_err(|e| e.to_string())
   122	        .and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string()))
   123	    {
   124	        Ok(v) => v,
   125	        Err(e) => {
   126	            eprintln!(
   127	                "recall: no ingested brain at {} ({e}); run `entire recall ingest` first",
   128	                brain_dir.display()
   129	            );
   130	            return ExitCode::FAILURE;
   131	        }
   132	    };
   133	    let brain = match FluctlightBrain::open_readonly(brain_dir) {
   134	        Ok(b) => b,
   135	        Err(e) => {
   136	            eprintln!("recall: open brain: {e}");
   137	            return ExitCode::FAILURE;
   138	        }
   139	    };
   140	    let cps: &[Checkpoint] = &input.checkpoints;
   141	    // Reach edges were folded into file engrams at ingest; rebuild the map
   142	    // from them so the scope check sees the same graph activate did not query.
   143	    let graph = graph_from_brain(&brain, cps);
   144	    let res = brain.activate_scoped(question, None, None, k.max(1) * 3);
   145	    let ranked: Vec<Ranked> = rerank(&res.recalls, cps, &graph)
   146	        .into_iter()
   147	        .take(k)
   148	        .collect();
   149	    println!("{}", serde_json::to_string(&ranked).unwrap_or_default());
   150	    ExitCode::SUCCESS
   151	}
   152	
   153	fn graph_from_brain(brain: &FluctlightBrain, cps: &[Checkpoint]) -> GraphReach {
   154	    let mut edges = std::collections::HashMap::new();
   155	    for cp in cps {
   156	        for f in &cp.files {
   157	            let res = brain.activate_scoped(
   158	                &format!("FILE {f} changed in {}", cp.commit_sha),
   159	                None,
   160	                None,
   161	                4,
   162	            );
   163	            for r in res.recalls {
   164	                let ctx = &r.episode.context;
   165	                let Some(file) = ctx.split_whitespace().find_map(|t| t.strip_prefix("file:"))
   166	                else {
   167	                    continue;
   168	                };
   169	                let Some(reach) = ctx
   170	                    .split_whitespace()
   171	                    .find_map(|t| t.strip_prefix("reaches:"))
   172	                else {
   173	                    continue;
   174	                };
   175	                if file == f && !reach.is_empty() {
   176	                    edges.entry(f.clone()).or_insert_with(|| {
   177	                        reach
   178	                            .split(',')
   179	                            .filter(|s| !s.is_empty())
   180	                            .map(str::to_string)
   181	                            .collect()
   182	                    });
   183	                }
   184	            }
   185	        }
   186	    }
   187	    GraphReach::from_map(edges)
   188	}
