    46	        "reverted", "disable", "strip", "stopped",
    47	    ];
    48	    let a = ADD.iter().filter(|w| toks.contains(*w)).count() as i8;
    49	    let r = REM.iter().filter(|w| toks.contains(*w)).count() as i8;
    50	    (a - r).signum()
