   122	pub fn cosine(a: &HashMap<String, f32>, b: &HashMap<String, f32>) -> f32 {
   123	    let dot: f32 = a.iter().filter_map(|(k, v)| b.get(k).map(|w| v * w)).sum();
   124	    let na: f32 = a.values().map(|v| v * v).sum::<f32>().sqrt();
   125	    let nb: f32 = b.values().map(|v| v * v).sum::<f32>().sqrt();
   126	    if na * nb == 0.0 { 0.0 } else { dot / (na * nb) }
   127	}
