pub fn symbol_lines_from_ndjson(
    touched: &[String],
    ndjson: &str,
    per_file: usize,
) -> Vec<(String, usize)> {
    let want: HashSet<&str> = touched.iter().map(String::as_str).collect();
    let mut by_file: HashMap<String, Vec<usize>> = HashMap::new();
